import{_ as a,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"08｜群策群力：Agent Teams多会话协作架构","description":"","frontmatter":{},"headers":[{"level":2,"title":"Sub-Agents vs Agent Teams：从“任务委托”到“团队协作”","slug":"sub-agents-vs-agent-teams-从-任务委托-到-团队协作","link":"#sub-agents-vs-agent-teams-从-任务委托-到-团队协作","children":[]},{"level":2,"title":"创建和使用 Agent Teams","slug":"创建和使用-agent-teams","link":"#创建和使用-agent-teams","children":[]},{"level":2,"title":"实战项目：全栈 Bug 猎人","slug":"实战项目-全栈-bug-猎人","link":"#实战项目-全栈-bug-猎人","children":[]},{"level":2,"title":"四大协作设计模式","slug":"四大协作设计模式","link":"#四大协作设计模式","children":[{"level":3,"title":"模式一：竞争假设（Competing Hypotheses）","slug":"模式一-竞争假设-competing-hypotheses","link":"#模式一-竞争假设-competing-hypotheses","children":[]},{"level":3,"title":"模式二：分层评审（Parallel Review）","slug":"模式二-分层评审-parallel-review","link":"#模式二-分层评审-parallel-review","children":[]},{"level":3,"title":"模式三：模块化开发（Module Ownership）","slug":"模式三-模块化开发-module-ownership","link":"#模式三-模块化开发-module-ownership","children":[]},{"level":3,"title":"模式四：规划-审批（Plan Approval）","slug":"模式四-规划-审批-plan-approval","link":"#模式四-规划-审批-plan-approval","children":[]}]},{"level":2,"title":"Sub-Agents vs Agent Teams：选型决策树","slug":"sub-agents-vs-agent-teams-选型决策树","link":"#sub-agents-vs-agent-teams-选型决策树","children":[]},{"level":2,"title":"Token 成本考量","slug":"token-成本考量","link":"#token-成本考量","children":[]},{"level":2,"title":"本讲小结","slug":"本讲小结","link":"#本讲小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/08｜群策群力：AgentTeams多会话协作架构.md","filePath":"ClaudeCode工程化实战/08｜群策群力：AgentTeams多会话协作架构.md","lastUpdated":1779815462000}'),i={name:"ClaudeCode工程化实战/08｜群策群力：AgentTeams多会话协作架构.md"};function p(l,e,o,g,c,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_08-群策群力-agent-teams多会话协作架构" tabindex="-1">08｜群策群力：Agent Teams多会话协作架构 <a class="header-anchor" href="#_08-群策群力-agent-teams多会话协作架构" aria-label="Permalink to &quot;08｜群策群力：Agent Teams多会话协作架构&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/e49107ce955f759ecedd2923675dfe4d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/e49107ce955f759ecedd2923675dfe4d.png" alt=""></a></p><p>你好，我是黄佳。欢迎来到 Claude Code 工程化实战的第 8 讲。这一讲也是SubAgent部分的终章。</p><p>前面四讲我们深入学习了子代理（Sub-Agents）——从核心概念到只读型、高噪声处理，再到并行探索和流水线编排的实操案例。今天我们要探索一个更进阶的（也是新鲜出炉的）协作模式： <strong>Agent Teams（智能体团队）</strong>。</p><blockquote><p><strong>注意</strong>：Agent Teams 是 Claude Code 的实验性功能，默认关闭。需要在相关级别的设置文件中（如用户级设置 ~/.claude/settings.json 或 项目级设置 project_folder/.claude/settings.json）添加 <code>CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS</code> 环境变量来启用。Claud Code官方说，这个实验性功能可能存在已知限制（具体限制可以参考官网实时更新的 <a href="https://code.claude.com/docs/en/agent-teams" target="_blank" rel="noreferrer">说明</a>，搜索“limitations”关键字），生产环境请谨慎评估。</p></blockquote><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/7e4207bae5ec09564408772c32ffd20e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/7e4207bae5ec09564408772c32ffd20e.jpg" alt=""></a></p><h2 id="sub-agents-vs-agent-teams-从-任务委托-到-团队协作" tabindex="-1">Sub-Agents vs Agent Teams：从“任务委托”到“团队协作” <a class="header-anchor" href="#sub-agents-vs-agent-teams-从-任务委托-到-团队协作" aria-label="Permalink to &quot;Sub-Agents vs Agent Teams：从“任务委托”到“团队协作”&quot;">​</a></h2><p>在前几讲中介绍的子代理工作模式虽然也各有差异，但是基本模式一致。都是主对话像老板一样，把任务 <strong>委派</strong> 给各个专职员工（子代理）。这种模式解决了上下文污染、权限边界、任务并行等问题。但它有一个根本性的限制： <strong>子代理只能向主对话汇报，不能互相交流。</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/e16fc5958229a18c5e7e37b5b5091314.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/e16fc5958229a18c5e7e37b5b5091314.jpg" alt=""></a></p><p>这在很多场景下足够好用。但我们在实际生产环境中可能会遇到更复杂、更诡异的场景：比如 <strong>多假设并行验证。</strong></p><p>你的系统出现了一个奇怪 bug——用户登录后偶尔会话丢失，没有明确的规律。你怀疑可能是：</p><ul><li><p>假设 A：JWT token 过期时间计算有问题</p></li><li><p>假设 B：Redis session 存储的竞态条件</p></li><li><p>假设 C：负载均衡器的 sticky session 配置</p></li></ul><p>如果用子代理，情况可能是这样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/01d8fb446e4cb8b70ab1d504753d212f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/01d8fb446e4cb8b70ab1d504753d212f.jpg" alt=""></a></p><p>如果子代理 B 能看到子代理 C 的发现，它可能会说：等等，Redis 连接数上限问题可能是因为 sticky session 5 分钟后切换了服务器，导致新的 Redis 连接被创建。</p><p><strong>这正是 Agent Teams 要解决的问题——让代理之间能够直接交流、互相挑战、协作推进。</strong></p><p>Agent Teams 让你可以协调多个 Claude Code 实例作为一个团队工作。一个会话作为 <strong>Team Lead（团队领导）</strong>，协调工作、分配任务、综合结果。 <strong>Teammates（队友）</strong> 各自独立工作，每个都有自己的上下文窗口，并且可以直接互相通信。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f15cffe029cdb4a021968c9bf5369a70.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f15cffe029cdb4a021968c9bf5369a70.jpg" alt=""></a></p><p>因此我们说，“Agent Teams模式”与“主会话-子代理模式”最本质的区别是， <strong>Teammates 可以互相发消息、共享发现、挑战彼此的结论。</strong></p><h2 id="创建和使用-agent-teams" tabindex="-1">创建和使用 Agent Teams <a class="header-anchor" href="#创建和使用-agent-teams" aria-label="Permalink to &quot;创建和使用 Agent Teams&quot;">​</a></h2><p>刚才说了，Agent Teams 默认是关闭的，启用方式是在 <code>settings.json</code> 中设置环境变量：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;env&quot;: {</span></span>
<span class="line"><span>    &quot;CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS&quot;: &quot;1&quot;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>或者在 shell 环境中设置：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS=1</span></span></code></pre></div><p>在 Claude Code 中可以通过下面两种方式创建团队。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/403517e39d0d294f54572b3078045f94.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/403517e39d0d294f54572b3078045f94.jpg" alt=""></a></p><p><strong>两种方式你都保持控制权</strong>——Claude 不会未经你批准就创建 team。</p><p>启用后，用自然语言告诉 Claude 创建团队并描述任务：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在设计一个 CLI 工具来追踪代码库中的 TODO 注释。</span></span>
<span class="line"><span>创建一个 agent team 从不同角度探索这个问题：</span></span>
<span class="line"><span>一个 teammate 负责 UX，一个负责技术架构（用最好的模型），一个扮演审评质疑者（用普通模型）。</span></span></code></pre></div><p>Claude 会建团队，生成指定的 Teammates让它们探索问题，然后综合各方发现，完成后清理团队。</p><p>团队成功创建后，一个 Agent Team 由以下组件构成。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/6278cf7d69d04aeb2e8ddeeee600bb3e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/6278cf7d69d04aeb2e8ddeeee600bb3e.jpg" alt=""></a></p><p>团队和任务相关的数据会存储在本地。</p><ul><li><p><strong>团队配置</strong>： <code>~/.claude/teams/{team-name}/config.json</code></p></li><li><p><strong>任务列表</strong>： <code>~/.claude/tasks/{team-name}/</code></p></li></ul><p>团队配置包含 <code>members</code> 数组，记录每个 Teammate 的名称、agent ID 和类型。Teammates 可以读取这个文件来发现其他团队成员。这些都是Claude Code自行搞定的，不需要我们操心去存放。</p><p>Agent Teams 支持两种显示模式：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/0fc8d9fd4155a600cc98eb26a226baf8.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/0fc8d9fd4155a600cc98eb26a226baf8.jpg" alt=""></a></p><p>完成工作后，Lead 会向Teammate发送关闭请求，Teammate 可以批准（优雅退出）或拒绝（并解释原因）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/ee210a4f07af7b8d96028e9b707b0136.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/ee210a4f07af7b8d96028e9b707b0136.jpg" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/569fed0cb067cde765fe553bac0d34d1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/569fed0cb067cde765fe553bac0d34d1.png" alt="图片"></a></p><p>最后，全部工作收尾，Lead 会清理团队，移除共享的团队资源。需要注意，如果出现需要用户人工指示清理的化，清理前先关闭所有 Teammates，而且应该只让 Lead 执行清理（Teammates 的 team 上下文可能不正确）。</p><h2 id="实战项目-全栈-bug-猎人" tabindex="-1">实战项目：全栈 Bug 猎人 <a class="header-anchor" href="#实战项目-全栈-bug-猎人" aria-label="Permalink to &quot;实战项目：全栈 Bug 猎人&quot;">​</a></h2><p>这里，我为本讲配套了一个完整的工程化实战项目，位于项目目录 <code>03-SubAgents/projects/06-agent-teams-bug-hunt/</code>。</p><p>项目场景是一个 Express.js 电商应用（ShopStream），其中刻意植入了多个相互关联 bug。用户报告了三个看似独立的症状：会话丢失、API 变慢、数据泄漏。真相是这些症状由相互 bug 的级联故障造成：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bug 1: DB 连接池太小（db.js）</span></span>
<span class="line"><span>    ↓ 连接耗尽</span></span>
<span class="line"><span>Bug 2: Redis Session 不处理重连（middleware/session.js）</span></span>
<span class="line"><span>    ↓ Session 写入静默失败</span></span>
<span class="line"><span>Bug 3: 订单查询 N+1 问题（routes/orders.js）</span></span>
<span class="line"><span>    ↓ 大量连接被占用 → 加剧 Bug 1</span></span>
<span class="line"><span>Bug 4: 缓存竞态条件（middleware/cache.js）</span></span>
<span class="line"><span>    ↓ 缓存 key 缺少用户标识 → 数据泄漏</span></span>
<span class="line"><span>    ... ...</span></span></code></pre></div><p>那么为什么这里需要 Agent Teams 呢？</p><p>因为单独调查者容易“锚定”，找到一个 bug 后就满意了，不继续挖掘。而bug 之间的关联需要跨视角发现，只有Session 侦探和数据库侦探各自的发现互相对照，才能看到级联效应。此外，架构侦探可以把其他侦探的发现串联起来，通过辩论机制产出更完整的根因链。</p><p>项目中具体的文件内容和说明如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f0ec886eb17df2e65afaf623a47499b1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f0ec886eb17df2e65afaf623a47499b1.jpg" alt=""></a></p><p>下面，我带着你一起动手试一下。我们启用 Agent Teams，用 team-prompt.md 中的指令启动团队，观察四个侦探如何各自调查、分享发现、互相挑战，最终拼出完整的级联故障链。</p><p>把team-prompt.md中介绍的某一种启动模式（我设计了多个Teams协同模式，这里只展示竞争假设模式）拷贝到Claude Code命令行中，启动Teams即可。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阅读 bug-report.md 中描述的三个症状。然后创建一个 agent team 来调查这些问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>生成 4 个 investigator teammates：</span></span>
<span class="line"><span>- &quot;Session 侦探&quot;：假设根因在 Session/Redis 层。重点审查 middleware/session.js 和 server.js 中的 session 配置。</span></span>
<span class="line"><span>- &quot;数据库侦探&quot;：假设根因在数据库连接和查询层。重点审查 db.js 和 routes/ 下所有路由的数据库操作。</span></span>
<span class="line"><span>- &quot;缓存侦探&quot;：假设根因在缓存机制。重点审查 middleware/cache.js 以及缓存与用户隔离相关的逻辑。</span></span>
<span class="line"><span>- &quot;架构侦探&quot;：不预设假设，从整体架构角度分析各组件的交互。重点关注错误处理、资源管理和并发安全。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个 teammate 的 prompt 中包含：</span></span>
<span class="line"><span>1. buggy-app/ 目录包含完整的应用代码</span></span>
<span class="line"><span>2. 他们需要用 Read/Grep/Glob 工具审查代码</span></span>
<span class="line"><span>3. 找到可疑问题后，要发消息告诉其他 teammates</span></span>
<span class="line"><span>4. 如果其他 teammate 的发现与自己的发现有关联，要主动指出</span></span>
<span class="line"><span>5. 特别注意：三个症状可能不是独立的，要寻找它们之间的因果关系</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求所有 teammates 在完成初步调查后互相分享发现，并尝试挑战彼此的结论。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终综合所有发现，生成一份按照 findings-template.md 格式的调查报告。</span></span></code></pre></div><p>我们用自然语言启动Teams。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/a84f2e71346e5fb18392eyyccc36a052.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/a84f2e71346e5fb18392eyyccc36a052.png" alt="图片"></a></p><p>Claude Code根据指示，阅读项目中相关的配置文档，开始创建Teams。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f72e27d378811e7aabcbcb9abd79a4ce.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f72e27d378811e7aabcbcb9abd79a4ce.png" alt="图片"></a></p><p>团队创建成功，Teams开始启动工作了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f709294f5330a99d7707f840c7279a13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f709294f5330a99d7707f840c7279a13.png" alt="图片"></a></p><p>一段时间后，4位 Bug 侦探完成了任务，Leader认为可以生产综合报告了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/faebd4yy93298dbf21f7b29daa5fbe25.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/faebd4yy93298dbf21f7b29daa5fbe25.png" alt="图片"></a></p><p>报告完成，leader要关闭teams了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/92829f7f6417c7f0c3a88d8bec4e9e01.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/92829f7f6417c7f0c3a88d8bec4e9e01.png" alt="图片"></a></p><p>显示调查结果总览。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/1c6d20aef927958e82e7eb120e390598.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/1c6d20aef927958e82e7eb120e390598.png" alt="图片"></a></p><p><strong>等等！有一位侦探发现，事儿还没完</strong>，还需要更多的根因分析和补充说明。于是它又开始更新报告……</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/569fed0cb067cde765fe553bac0d34d1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/569fed0cb067cde765fe553bac0d34d1.png" alt="图片"></a></p><p>终于完成了任务，全部Bug被发现！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/1edd0552563dc17ecec438a78eb0c337.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/1edd0552563dc17ecec438a78eb0c337.png" alt="图片"></a></p><h2 id="四大协作设计模式" tabindex="-1">四大协作设计模式 <a class="header-anchor" href="#四大协作设计模式" aria-label="Permalink to &quot;四大协作设计模式&quot;">​</a></h2><p>Agent Teams 最强大的地方在于它支持的协作模式。我从官方文档和工程实践中提炼出四种核心设计模式。</p><h3 id="模式一-竞争假设-competing-hypotheses" tabindex="-1">模式一：竞争假设（Competing Hypotheses） <a class="header-anchor" href="#模式一-竞争假设-competing-hypotheses" aria-label="Permalink to &quot;模式一：竞争假设（Competing Hypotheses）&quot;">​</a></h3><p>这种模式适用于根因不明确，需要从多个方向同时验证的场景。</p><p>单个 Agent 调查时容易“锚定”——找到一个合理解释后就停止探索，可能错过真正的根因。此时，让多个 Teammates 各自持有不同假设，并要求它们互相挑战、试图推翻对方的理论。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户报告应用在发送一条消息后就退出了，而不是保持连接。</span></span>
<span class="line"><span>生成 5 个 agent teammates 调查不同的假设。</span></span>
<span class="line"><span>让它们互相对话，试图推翻对方的理论，像科学辩论一样。</span></span>
<span class="line"><span>将最终共识更新到 findings 文档。</span></span></code></pre></div><p>该模式架构如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/b11efd96dab512c14e6008e0d8fb0a72.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/b11efd96dab512c14e6008e0d8fb0a72.jpg" alt=""></a></p><p>想一想，这种模式的工程价值在哪里？</p><ul><li><p>避免锚定效应——多个独立调查者，各自寻找证据支持自己的假设。</p></li><li><p>辩论机制迫使每个假设必须经受挑战才能“存活”。</p></li><li><p>最终“存活”的假设更可能是真正的根因。</p></li></ul><p>为什么辩论结构是此处的关键机制？顺序调查会受到锚定偏见的影响，一旦第一个理论被探索，后续调查会不自觉地偏向它。多个独立调查者主动互相反驳，幸存下来的理论更可能是真正的根因。</p><h3 id="模式二-分层评审-parallel-review" tabindex="-1">模式二：分层评审（Parallel Review） <a class="header-anchor" href="#模式二-分层评审-parallel-review" aria-label="Permalink to &quot;模式二：分层评审（Parallel Review）&quot;">​</a></h3><p>这种模式适用于代码审查、PR Review 等需要从多个维度同时评估的任务。</p><p>因为单个 reviewer 容易聚焦于某一类问题（比如只看代码风格），而忽略其他维度。让多个 Teammates 各自负责不同的审查维度，同时工作。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建一个 agent team 来审查 PR #142。生成三个 reviewer：</span></span>
<span class="line"><span>- 一个专注安全隐患</span></span>
<span class="line"><span>- 一个检查性能影响</span></span>
<span class="line"><span>- 一个验证测试覆盖</span></span>
<span class="line"><span>让它们各自审查并汇报发现。</span></span></code></pre></div><p>该模式架构如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/6acbf41ed06d3658e52d825c857bea95.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/6acbf41ed06d3658e52d825c857bea95.jpg" alt=""></a></p><p>这种模式的工程价值有哪些呢？</p><ul><li><p>每个维度都得到充分关注，不会因为注意力分散而遗漏。</p></li><li><p>并行执行，时间成本不增加</p></li><li><p>不同专家可能发现关联问题（Security Reviewer 发现的输入验证问题可能影响 Performance）</p></li></ul><h3 id="模式三-模块化开发-module-ownership" tabindex="-1">模式三：模块化开发（Module Ownership） <a class="header-anchor" href="#模式三-模块化开发-module-ownership" aria-label="Permalink to &quot;模式三：模块化开发（Module Ownership）&quot;">​</a></h3><p>这种模式适用于新功能开发，涉及多个独立模块（前端、后端、数据库、测试）的场景。</p><p>由于让一个 Agent 依次开发容易混淆上下文，多个子代理并行又无法协调接口。因此，让每个 Teammate 拥有一个模块，通过共享任务列表协调工作。</p><p>该模式架构如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/766d16b099c22b7ba9822f0845c0d69a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/766d16b099c22b7ba9822f0845c0d69a.jpg" alt=""></a></p><p>这种模式的关键机制是：</p><ul><li><p>任务依赖：任务可以声明依赖其他任务，被阻塞的任务不能被认领。</p></li><li><p>自动解锁：当依赖任务完成后，被阻塞的任务自动变为可认领。</p></li><li><p>文件所有权：每个 Teammate 负责不同的文件，避免冲突。</p></li></ul><h3 id="模式四-规划-审批-plan-approval" tabindex="-1">模式四：规划-审批（Plan Approval） <a class="header-anchor" href="#模式四-规划-审批-plan-approval" aria-label="Permalink to &quot;模式四：规划-审批（Plan Approval）&quot;">​</a></h3><p>这种模式适用于复杂或高风险任务，需要在实施前确认方案。</p><p>如果直接让 Teammate 开干，可能因方向错误导致返工。因此要求 Teammate 在实施前先提交计划，Lead 审批通过后才能执行。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成一个 architect teammate 来重构认证模块。</span></span>
<span class="line"><span>要求在修改任何代码前先提交计划等待审批。</span></span></code></pre></div><p>该模式工作流如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/723d64913d2e7950604dd98dd85044a0.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/723d64913d2e7950604dd98dd85044a0.jpg" alt=""></a></p><p>控制 Lead 的审批标准：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成一个 architect teammate 来重构认证模块。</span></span>
<span class="line"><span>要求在修改任何代码前先提交计划等待审批。</span></span>
<span class="line"><span>只批准包含测试计划的方案。</span></span>
<span class="line"><span>拒绝任何修改数据库 schema 的方案。</span></span></code></pre></div><p>Lead 会根据你提供的标准自主做出批准/拒绝决策。你影响 Lead 判断的方式是在 prompt 中给出明确的标准，比如“只批准包含测试覆盖的方案”或“拒绝修改数据库 schema 的方案”。</p><p>好，本讲主要内容就到这里，关于更多Teams的当前局限，权限配置等等，请参考 <a href="https://code.claude.com/docs/en/agent-teams" target="_blank" rel="noreferrer">官网文档</a> 中的说明，我就不一一赘述了。不过呢，结束之前，下面再给出两个重要小内容。</p><h2 id="sub-agents-vs-agent-teams-选型决策树" tabindex="-1">Sub-Agents vs Agent Teams：选型决策树 <a class="header-anchor" href="#sub-agents-vs-agent-teams-选型决策树" aria-label="Permalink to &quot;Sub-Agents vs Agent Teams：选型决策树&quot;">​</a></h2><p>你可能还有这样的疑惑：到底Sub-Agents 和 Agent Teams这两种架构如何选择？</p><p>这里给出一个选型决策树。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的任务需要多个 workers 吗？</span></span>
<span class="line"><span>├── 否 → 直接在主对话或用单个子代理</span></span>
<span class="line"><span>└── 是 → Workers 需要互相通信吗？</span></span>
<span class="line"><span>    ├── 否 → Sub-Agents</span></span>
<span class="line"><span>    │   └── 特点：</span></span>
<span class="line"><span>    │       • 更低 token 成本</span></span>
<span class="line"><span>    │       • 更简单的协调</span></span>
<span class="line"><span>    │       • 适合：并行探索、流水线编排</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── 是 → Agent Teams</span></span>
<span class="line"><span>        └── 特点：</span></span>
<span class="line"><span>            • 支持讨论和挑战</span></span>
<span class="line"><span>            • 共享任务列表</span></span>
<span class="line"><span>            • 适合：竞争假设、协作开发、多角度审查</span></span></code></pre></div><p>我们用一张表格厘清两种模式的差异。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f0c0e760794924353028e8d99bb37c58.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/f0c0e760794924353028e8d99bb37c58.jpg" alt=""></a></p><p>一句话总结，核心判断标准是你的 workers 是否需要互相通信？Sub-Agents是快速、廉价的“派出去-带回来”模式，如果 <strong>只需汇报结果</strong> ，就选 Sub-Agents；Agent Teams是复杂、协作的“组队讨论”模式，如果 <strong>需要互相讨论、挑战、协调</strong> ，就选 Agent Teams。</p><h2 id="token-成本考量" tabindex="-1">Token 成本考量 <a class="header-anchor" href="#token-成本考量" aria-label="Permalink to &quot;Token 成本考量&quot;">​</a></h2><p>最后说说成本。Claude指出，Agent Teams 使用的 token 显著高于单会话或子代理，因为每个 Teammate 是独立的 Claude 实例，有独立的上下文窗口。消息通信消耗额外 token，而且团队越大，成本越高。</p><p>因此，适合 Agent Teams 的任务特征包括：</p><ul><li><p>并行探索能带来真正的价值；</p></li><li><p>讨论和挑战能提高结果质量；</p></li><li><p>任务复杂度值得额外成本。</p></li></ul><p>不适合 Agent Teams 的任务特征包括：</p><ul><li><p>常规任务，单会话就够；</p></li><li><p>任务之间没有协作需求以及预算有限的场景。</p></li></ul><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><p>Agent Teams 让多个 Claude Code 实例作为团队协作，Teammates 可以互相通信，而不只是向主对话汇报。其核心组件包括 Lead（协调者）， Teammates（执行者）， Task List（共享任务）， Mailbox（消息系统）。</p><p>我们给出了一个实操案例，同时介绍了4大Teams应用模式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/4584aa6698af626a3bbcf52cbaa827b6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/945358/4584aa6698af626a3bbcf52cbaa827b6.jpg" alt=""></a></p><p>这里也给出Claude Code总结的Teams最佳实践。</p><ol><li><p>给 Teammates 足够的上下文。Teammates 不继承 Lead 的对话历史，所以生成时要给足信息。</p></li><li><p>合理拆分任务粒度。太小的话协调开销超过收益，过大则Teammate 工作太久无检查点，增加返工风险。任务最好是自包含的单元，产出明确的交付物（一个函数、一个测试文件、一份审查报告）。每个 Teammate 5-6 个任务比较合适。让所有人保持忙碌，也便于 Lead 在某人卡住时重新分配。</p></li><li><p>避免文件冲突。两个 Teammates 编辑同一个文件会导致覆盖。拆分工作时确保每个 Teammate 拥有不同的文件集。</p></li><li><p>监控并引导。不要让 team 无人看管运行太久。定期检查进度，纠正偏离方向的 Teammate，在发现问题时及时综合。</p></li><li><p>从研究和审查任务开始。如果你刚接触 Agent Teams，从边界清晰、不写代码的任务开始，如审查 PR、调研技术方案、调查 bug等，这些任务能展示并行探索的价值，又避免了并行写代码的协调挑战。</p></li><li><p>让 Lead 等待 Teammates 完成。有时 Lead 会在 Teammates 完成前就自己开始下一步工作。如果发现这种情况，可以在命令行提示“等待你的 teammates 完成任务后再继续”。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>回顾你之前用子代理做的任务。有哪些场景如果用 Agent Teams 的“竞争假设”模式可能效果更好？</p></li><li><p>在”模块化开发“模式中，如果两个 Teammates 需要修改同一个接口文件（比如定义 API 契约），你会如何处理文件冲突问题？</p></li><li><p>对比 Sub-Agents 的“流水线编排”和 Agent Teams 的规划-审批模式。两者解决的问题有什么不同？在什么场景下你会选择哪个？</p></li><li><p>假设你要用 Agent Teams 做一次技术方案评审——有三个 Teammates 分别代表“性能优先”“可维护性优先”“快速交付优先”三种立场。设计一下你会给 Lead 什么指令，让这场讨论产出高质量的决策。</p></li><li><p>在“全栈 Bug 猎人”项目中，四个 bug 的级联关系是如何被发现的？如果用子代理（而非 Agent Teams）调查这些 bug，你预期会有什么不同的结果？具体到哪些关联会被遗漏？</p></li></ol><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>至此我们终于完成了子代理和 Agent Teams 的学习，我们对 Claude Code 的“多代理协作能力”已经有了完整的理解。从下一讲开始，我们将进入新的主题： <strong>Skills 技能系统</strong>。</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，别忘了分享给身边更多朋友。</p>`,128)])])}const u=a(i,[["render",p]]);export{h as __pageData,u as default};
